for q in Q:
 sid=q['sample_id'];x=cases[sid];tic=q['tic'];d=B/tic;d.mkdir(exist_ok=True)
 novelty='KNOWN' if sid=='F008' else 'SCOPED_NONMATCH'
 report=(f"# {sid} TIC {tic}: {x['v']}\n\n"
 f"Selected stratum: {q['sample_stratum']}; original priority rank {q['priority_rank']}. Bounded physical review complete. Catalogue status: {novelty}.\n\n"
 f"## Raw events and alternative extraction\n\n{x['raw']}\n\n"
 f"## Timing, source and Gaia geometry\n\n{x['physics']}\n\n"
 f"## Limits and next check\n\n{x['limits']} Next: {x['next']}\n\n"
 f"## Evidence and scope\n\nVerified source FITS identities and hashes: `../../source-packets/{tic}/sources.json`. Raw q0 context: `all-sectors.png`, `ranked-windows.png`, `screen.json`; provisional local fits: `fitted-windows.json` and plot. Hand-selected cycle arithmetic: `../review-clocks.json`. Source-specific Gaia diagnostics: `../gaia-geometry.json` and F002 `../abfg-geometry.json`. Independent same-photon TESSCut and WCS: `../helper-audit.md` plus helper-prefixed artifacts. Current sector availability: `../../root-availability.json`. Queue-scoped catalogue receipts: `../../shared-catalogues/TARGET-STATUS.csv` and `target-evidence.json`. F006 repeat morphology and invalid S65: `../f006-overlay.json`, `../f006-s65.json`; F007 shorter aliases and visual null comparison: `../f007-aliases.json`, `../f007-null-preview.png`; F008 partial-cycle coverage and two-kind interval arithmetic: `../helper-F008-coverage.json`, `../helper-F008-deep-coverage.json`, `../f008-cycle-intersection.json`; F010 raw overlay and unresolved aliases: `../f010-overlay.json`, `../f010-aliases.json`. Screening centers are predictions; fitted local centers with singular or bound-hitting covariance are not precision epochs. No source in another reduction supplies a new observing occasion.\n")
 (d/'REPORT.md').write_text(report,encoding='utf8')
 rows.append({'sample_id':sid,'tic':tic,'sample_stratum':q['sample_stratum'],'physical_verdict':x['v'],'full_review_completion':'COMPLETE','novelty_status':novelty,'period_days':x['p'],'period_error_days':'','primary_epoch_btjd':x['epoch'],'depth_ppt':x['depth'],'limitations':x['limits'],'next_check':x['next'],'report':str(d/'REPORT.md')})
with (B/'RESULTS.csv').open('w',newline='',encoding='utf8') as f:
 w=csv.DictWriter(f,fields);w.writeheader();w.writerows(rows)
